import cv2,numpy as np
im=cv2.imread('first_frame.png')
# row edge info based on color distance from row local smooth median of outside
for y in range(10,115,5):
 vals=[]
 for x in range(110,198):
  b,g,r=map(float,im[y,x]);
  # paper is near-neutral bright or shaded; background right has cool blue, left blue/table
  # target paper: r roughly g and b slightly higher
  if abs(r-g)<16 and b-r<18 and min(b,g,r)>70:
   vals.append(x)
 if vals:
  # group lengths >=3
  groups=[];st=pr=vals[0]
  for x in vals[1:]:
   if x>pr+1:
    if pr-st>=2: groups.append((st,pr))
    st=x
   pr=x
  if pr-st>=2:groups.append((st,pr))
  print(y,groups)
PY"
